def ld(path,title,desc,crumbs):
    org={"@type":["ProfessionalService","Organization"],"@id":D+"/#org","name":NAME,"url":D+"/","logo":D+"/favicon.svg","image":D+"/og.png","description":"Software studio building a multi-agent AI platform: one commander coordinating 99+ specialised assistants.","areaServed":"Worldwide","priceRange":"$$"}
    org["founder"]={"@type":"Person","name":"Nikhil Chary Sriramoju"};org["sameAs"]=["https://github.com/Nikhil-creat","https://in.linkedin.com/in/nikhil-chary-sriramoju-95041b38a"]
    ad={k:v for k,v in {"@type":"PostalAddress","addressLocality":os.environ.get("BIZ_LOCALITY"),"addressRegion":os.environ.get("BIZ_REGION"),"addressCountry":os.environ.get("BIZ_COUNTRY")}.items() if v}
    if len(ad)>1:org["address"]=ad
    for ev,k in (("BIZ_PHONE","telephone"),("CONTACT_EMAIL","email")):
        if os.environ.get(ev):org[k]=os.environ[ev]
    bl={"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":i+1,"name":n,"item":D+u} for i,(n,u) in enumerate(crumbs)]}
    g=[org,{"@type":"WebSite","@id":D+"/#site","url":D+"/","name":NAME,"publisher":{"@id":D+"/#org"}},{"@type":"WebPage","url":D+path,"name":title,"description":desc,"isPartOf":{"@id":D+"/#site"}},bl]
    return '<script type="application/ld+json">'+json.dumps({"@context":"https://schema.org","@graph":g})+'</script>'
def head(path,title,desc,crumbs,extra=""):
    t=html.escape(title);d=html.escape(desc);rb='' if 'noindex' in extra else '<meta name="robots" content="index,follow,max-image-preview:large">'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<script>try{{var t=localStorage.getItem("jw-theme");if(t)document.documentElement.dataset.theme=t}}catch(e){{}}</script><title>{t}</title><meta name="description" content="{d}"><link rel="canonical" href="{D}{path}"><meta name="theme-color" content="#EEF0F2"><meta name="author" content="Nikhil Chary Sriramoju"><meta name="build" content="{BUILD}">{rb}<link rel="author" href="/humans.txt"><link rel="apple-touch-icon" href="/icon-192.png">
<meta name="jarwis-api" content="/api/chat"><link rel="manifest" href="/manifest.webmanifest"><link rel="icon" href="/favicon.ico" sizes="48x48"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="sitemap" href="/sitemap.xml">
<meta property="og:type" content="website"><meta property="og:site_name" content="{NAME}"><meta property="og:title" content="{t}"><meta property="og:description" content="{d}"><meta property="og:url" content="{D}{path}"><meta property="og:image" content="{D}/og.png"><meta property="og:image:alt" content="Jarwis: a commander AI coordinating 99+ assistants"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{t}"><meta name="twitter:description" content="{d}"><meta name="twitter:image" content="{D}/og.png">
<link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preload" as="style" href="{FONTS}" onload="this.onload=null;this.rel='stylesheet'"><noscript><link rel="stylesheet" href="{FONTS}"></noscript><link rel="stylesheet" href="/assets/site.css">
{ld(path,title,desc,crumbs)}{extra}</head>'''
def navbar(path):
    ls="".join(f'<a href="{u}"{" aria-current=page" if path==u else ""}>{n}</a>' for u,n in NAV)
    return f'<a class="skip" href="#main">Skip to content</a><header class="nav"><a class="logo" href="/" aria-label="{NAME} home">{LOGO}Jarwis</a><nav aria-label="Main">{ls}</nav><button class="mb" type="button" aria-label="Menu" aria-expanded="false">Menu</button><a class="btn" href="/assistants/">Meet the assistants</a><button class="tg" type="button" aria-label="Toggle dark mode" aria-pressed="false">Theme</button></header>'
def foot():
    return f'''<footer><div><strong style="color:#fff">{NAME}</strong><p style="margin-top:8px;max-width:38ch">One commander and 99 specialist AI assistants. Plans, drafts and checklists you review and approve.</p></div><div><h2>Explore</h2><a href="/">Home</a><a href="/assistants/">Assistants</a><a href="/architecture/">Architecture</a><a href="/security/">Security</a><a href="/roadmap/">Roadmap</a><a href="/resume/">Resume</a><a href="/interview/">Interview</a><a href="/tools/">Live data</a><a href="/status/">Status</a><a href="/builder/">Builder</a></div><div><h2>Site</h2><a href="/sitemap.xml">Sitemap</a><a href="/llms.txt">llms.txt</a><a href="/robots.txt">robots.txt</a><a href="/faq/">FAQ</a><a href="/contact/">Contact</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><p style="margin-top:10px">&copy; {datetime.date.today().year} {NAME}</p><p style="margin-top:6px">Designed and developed by <a style="display:inline;color:#fff" href="/builder/">Nikhil Chary Sriramoju</a></p><p style="margin-top:6px;font-size:12px;opacity:.7">Build {BUILD}</p></div></footer>'''
def crumbs(cs):
    return '<nav class="crumbs" aria-label="Breadcrumb"><ol>'+"".join(f'<li><a href="{u}">{n}</a></li>' if i<len(cs)-1 else f'<li aria-current="page">{n}</li>' for i,(n,u) in enumerate(cs))+'</ol></nav>'
def w(path,s):
    fp=("."+path+"index.html") if path.endswith("/") else "."+path
    os.makedirs(os.path.dirname(fp) or ".",exist_ok=True);open(fp,"w",encoding="utf-8").write(s)
