inner("/architecture/","System Architecture | Jarwis","How Jarwis works today, and the architecture it is growing into.","Architecture",
'''<section><h2>Live today</h2><div class="grid"><div class="tile"><h3>Mission engine</h3><p>Commander-00 plans, specialists work in parallel, you approve one combined result.</p></div><div class="tile"><h3>AI gateway</h3><p>A Vercel function that detects Groq and Gemini models and falls back between them.</p></div><div class="tile"><h3>99 assistants</h3><p>Each has a role, tools and its own saved chat.</p></div><div class="tile"><h3>Career tools</h3><p>ATS resume, cover letter and interview practice.</p></div></div></section><section><h2>Target architecture</h2><p>The full design Jarwis is growing into. The pieces listed under Live today already work.</p><pre class="mm">You (voice / chat / PWA)
  -> Commander-00 (LangGraph supervisor, budget governor)
      -> A2A mesh -> 99+ assistants
           -> MCP bus: files, Git, DB, calendar, browser
           -> Hybrid RAG: Qdrant + BM25 + reranker + graph
           -> Vision worker (PyTorch / ONNX)
           -> Docker sandbox + tests -> self-repair (max 3)
      -> HITL approval gate -> deploy / send / push
  Telemetry: OpenTelemetry -> Prometheus -> Grafana</pre></section>
<section><h2>Building blocks</h2><div class="grid"><div class="tile"><h3>Control plane</h3><p>Next.js command centre with live swarm graph and approval queue.</p></div><div class="tile"><h3>Execution plane</h3><p>FastAPI, LangGraph, Redis Streams and Docker sandbox runner.</p></div><div class="tile"><h3>Model router</h3><p>Auto-discovers Gemini, Groq, OpenAI, Anthropic and Ollama, with fallback.</p></div><div class="tile"><h3>Storage</h3><p>PostgreSQL, Qdrant, MinIO and signed audit logs.</p></div></div></section><section><h2>Next</h2><p>Read how we protect it on the <a href="/security/">security page</a>.</p></section>''',"Architecture")
inner("/security/","Security and Human Approval | Jarwis","How Jarwis protects your data and keys: server-side keys, rate limits, approval before anything is saved or exported, and no trackers.","Security",
'<section><div class="grid"><div class="tile"><h3>Approval first</h3><p>Mission results are only saved and exported after you approve them. Jarwis cannot deploy, send or delete anything on its own.</p></div><div class="tile"><h3>Spend caps</h3><p>Mission Control stops adding specialists when your estimated token budget is used.</p></div><div class="tile"><h3>Isolation</h3><p>The AI keys stay on the server and are never sent to your browser. Requests are rate limited.</p></div><div class="tile"><h3>Privacy</h3><p>No accounts or trackers. Your resume name, email and phone stay in your browser.</p></div></div></section><section><h2>Related</h2><p>See the <a href="/architecture/">architecture</a> and the <a href="/assistants/">assistant registry</a>.</p></section>',"Security")
