import re as _re
for _r,_d,_f in os.walk("."):
    if _r.startswith("./.git") or "node_modules" in _r: continue
    for _n in _f:
        if _n.endswith(".html"):
            _p=os.path.join(_r,_n);_t=open(_p,encoding="utf-8").read();_u=_re.sub(r'(/assets/\w+\.(?:js|css))"',r'\1?v='+BUILD+'"',_t)
            if _u!=_t: open(_p,"w",encoding="utf-8").write(_u)
